// Package: Microsoft.ApplicationInsights.AspNetCore
// Install: dotnet add package Microsoft.ApplicationInsights.AspNetCore

using Microsoft.ApplicationInsights;
using Microsoft.ApplicationInsights.Extensibility;

var builder = WebApplication.CreateBuilder(args);

// Enable Application Insights telemetry
builder.Services.AddApplicationInsightsTelemetry(options =>
{
    options.ConnectionString = builder.Configuration["ApplicationInsights:ConnectionString"]!;
    options.EnableAdaptiveSampling = true;
    options.EnableQuickPulseMetricStream = true;
});

// Optional: configure sampling to reduce telemetry costs
builder.Services.Configure<TelemetryConfiguration>((config) =>
{
    config.DisableTelemetry = false;
});

var app = builder.Build();
app.MapGet("/", () =>
{
    Console.WriteLine("Request tracked by Application Insights");
    return Results.Ok("Hello from monitored app");
});
app.Run();

// Expected output in Application Insights portal:
// Request: GET / with 200 status, duration ~10ms

