using Microsoft.ApplicationInsights;
using Microsoft.ApplicationInsights.DataContracts;
using Microsoft.Extensions.Logging;

public class CheckoutService
{
    private readonly TelemetryClient _telemetry;
    private readonly ILogger<CheckoutService> _logger;

    public CheckoutService(TelemetryClient telemetry, ILogger<CheckoutService> logger)
    {
        _telemetry = telemetry;
        _logger = logger;
    }

    public async Task ProcessAsync(Order order, CancellationToken ct = default)
    {
        var stopwatch = System.Diagnostics.Stopwatch.StartNew();
        var properties = new Dictionary<string, string>
        {
            ["OrderId"] = order.Id,
            ["Region"] = order.Region,
            ["UserId"] = order.UserId
        };

        try
        {
            _telemetry.TrackEvent("CheckoutStarted", properties);
            _logger.LogInformation("Checkout started for order {OrderId}", order.Id);

            // business logic
            await SaveOrderAsync(order, ct);

            stopwatch.Stop();
            _telemetry.GetMetric("CheckoutDurationMs").TrackValue(stopwatch.ElapsedMilliseconds);
            _telemetry.TrackEvent("CheckoutCompleted", properties);
            _logger.LogInformation("Checkout completed for order {OrderId} in {Duration}ms",
                order.Id, stopwatch.ElapsedMilliseconds);
        }
        catch (Exception ex)
        {
            _telemetry.TrackException(ex, properties);
            _logger.LogError(ex, "Checkout failed for order {OrderId}", order.Id);
            throw;
        }
    }

    private Task SaveOrderAsync(Order order, CancellationToken ct)
        => Task.CompletedTask; // Replace with real persistence
}

public class Order
{
    public string Id { get; set; } = Guid.NewGuid().ToString();
    public string UserId { get; set; } = string.Empty;
    public string Region { get; set; } = string.Empty;
    public decimal Total { get; set; }
}

// Expected output in Application Insights portal:
// CustomEvent: CheckoutStarted (OrderId, Region, UserId)
