using Microsoft.ApplicationInsights;
using Microsoft.ApplicationInsights.DataContracts;

public class PostsController : ControllerBase
{
    private readonly ILogger<PostsController> _logger;
    private readonly BlogContext _db;
    private readonly TelemetryClient _telemetry;

    public PostsController(ILogger<PostsController> logger, BlogContext db, TelemetryClient telemetry)
    {
        _logger = logger;
        _db = db;
        _telemetry = telemetry;
    }

    [HttpGet("{id}")]
    public async Task<ActionResult<Post>> Get(int id, CancellationToken ct)
    {
        using var operation = _telemetry.StartOperation<DependencyTelemetry>("GetPost");
        _logger.LogInformation("Fetching post {PostId} from Azure SQL", id);

        var post = await _db.Posts.FindAsync(new object[] { id }, ct);

        if (post is null)
        {
            _logger.LogWarning("Post {PostId} not found", id);
            _telemetry.TrackEvent("PostNotFound", new Dictionary<string, string>
            {
                ["PostId"] = id.ToString()
            });
            return NotFound();
        }

        _telemetry.TrackEvent("PostFetched", new Dictionary<string, string>
        {
            ["PostId"] = post.Id.ToString(),
            ["TitleLength"] = post.Title.Length.ToString()
        });
        return Ok(post);
    }
}

// Expected output in Application Insights:
// Trace: 'Fetching post 1 from Azure SQL' with OperationId linked to request
// Event: PostFetched (on success) or PostNotFound (on 404)
// Dependency: GetPost tracked with response code and duration
